CREATE TABLE test_cleanup_runs(id TEXT PRIMARY KEY,actor TEXT NOT NULL,status TEXT NOT NULL,plan_hash TEXT NOT NULL,manifest TEXT NOT NULL,backup_key TEXT,created_at TEXT NOT NULL,completed_at TEXT);
CREATE TABLE test_cleanup_locks(order_id INTEGER PRIMARY KEY,run_id TEXT NOT NULL REFERENCES test_cleanup_runs(id));
CREATE TRIGGER cleanup_lock_orders_insert BEFORE INSERT ON orders WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_orders_update BEFORE UPDATE ON orders WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_claims_insert BEFORE INSERT ON claims WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_claims_update BEFORE UPDATE ON claims WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_quotes_insert BEFORE INSERT ON quotes WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_quotes_update BEFORE UPDATE ON quotes WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_invoices_insert BEFORE INSERT ON invoices WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_invoices_update BEFORE UPDATE ON invoices WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_subscriptions_insert BEFORE INSERT ON subscriptions WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_subscriptions_update BEFORE UPDATE ON subscriptions WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_subscription_deliveries_insert BEFORE INSERT ON subscription_deliveries WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_lock_subscription_deliveries_update BEFORE UPDATE ON subscription_deliveries WHEN EXISTS(SELECT 1 FROM test_cleanup_locks WHERE order_id=NEW.order_id) BEGIN SELECT RAISE(ABORT,'Test order is locked for cleanup'); END;
CREATE TRIGGER cleanup_customer_update BEFORE UPDATE ON customers WHEN EXISTS(SELECT 1 FROM orders o JOIN test_cleanup_locks l ON l.order_id=o.id WHERE o.customer_id=OLD.id) BEGIN SELECT RAISE(ABORT,'Test customer is locked for cleanup'); END;
CREATE TRIGGER cleanup_order_customer_insert BEFORE INSERT ON orders WHEN EXISTS(SELECT 1 FROM orders o JOIN test_cleanup_locks l ON l.order_id=o.id WHERE o.customer_id=NEW.customer_id) BEGIN SELECT RAISE(ABORT,'Test customer is locked for cleanup'); END;
CREATE TRIGGER cleanup_email_insert BEFORE INSERT ON email_deliveries WHEN EXISTS(SELECT 1 FROM invoices i JOIN test_cleanup_locks l ON l.order_id=i.order_id WHERE i.id=NEW.invoice_id) BEGIN SELECT RAISE(ABORT,'Test invoice is locked for cleanup'); END;
CREATE TRIGGER cleanup_run_commit_guard BEFORE UPDATE OF status ON test_cleanup_runs WHEN NEW.status='objects_pending' AND (OLD.status!='backing_up' OR NEW.backup_key IS NULL) BEGIN SELECT RAISE(ABORT,'Cleanup backup is not ready or run was aborted'); END;
